insert into public.substrate_components
  (id, label, family, packing_role, total_porosity, interparticle_void, spread, vg_alpha, vg_n, vg_theta_s, vg_theta_r, tier, source, note)
values
  ('potting-mix', 'Bagged potting mix', 'blend', 'matrix', 0.87, 0, 0.08, 0.143, 1.42, 0.87, 0.1, 'published-anchors', 'Fitted to published peat-based container-mix figures (see lib/soilProfile.ts)', 'A peat- or coir-based multipurpose compost, usually already containing some perlite.'),
  ('peat', 'Sphagnum peat', 'organic', 'matrix', 0.84, 0, 0.07, 0.21523, 1.43035, 0.84, 0.25, 'published-anchors', 'University of Arkansas Greenhouse Management, Unit 7 (substrate physical properties, 4-inch container): chosen so an 80:20 peat–perlite blend reproduces the published 79% porosity / 68% water / 10% air', 'Hard to re-wet once it dries right out.'),
  ('coir', 'Coco coir', 'organic', 'matrix', 0.86, 0, 0.08, 0.16997, 1.41546, 0.86, 0.25, 'published-anchors', 'University of Arkansas Greenhouse Management, Unit 7 (substrate physical properties, 4-inch container): chosen so an 80:20 coir–perlite blend reproduces the published 81% / 73% / 8%', 'Varies widely between sources and with the pith-to-fibre ratio (Abad et al. 2005).'),
  ('pine-bark', 'Pine bark fines', 'organic', 'matrix', 0.8, 0, 0.08, 0.67437, 1.37809, 0.8, 0.25, 'published-anchors', 'University of Arkansas Greenhouse Management, Unit 7 (substrate physical properties, 4-inch container): about 80% porosity and 22% air space', 'Aged, screened under about 1 cm. Fresh or coarser bark holds less.'),
  ('perlite', 'Perlite', 'aggregate', 'skeleton', 0.75, 0.4, 0.08, 1.2306, 1.42057, 0.75, 0.2, 'published-anchors', 'University of Arkansas Greenhouse Management, Unit 7 (substrate physical properties, 4-inch container): about 75% porosity and 30% air space', 'Horticultural (coarse) grade.'),
  ('pumice', 'Pumice', 'aggregate', 'skeleton', 0.65, 0.4, 0.1, 1.8301, 1.37902, 0.65, 0.18, 'typical-magnitude', 'Typical magnitude from the container-media literature (De Boodt & Verdonck 1972; Bunt 1988; Handreck & Black 2002); not a single measurement', '3–8 mm grade.'),
  ('vermiculite', 'Vermiculite', 'aggregate', 'skeleton', 0.85, 0.25, 0.1, 0.84039, 1.34633, 0.85, 0.25, 'typical-magnitude', 'Typical magnitude from the container-media literature (De Boodt & Verdonck 1972; Bunt 1988; Handreck & Black 2002); not a single measurement', 'Collapses with handling and age, holding more water and less air over time.'),
  ('orchid-bark', 'Orchid bark (chunks)', 'organic', 'skeleton', 0.78, 0.45, 0.1, 5.01187, 1.39805, 0.78, 0.15, 'typical-magnitude', 'Typical magnitude from the container-media literature (De Boodt & Verdonck 1972; Bunt 1988; Handreck & Black 2002); not a single measurement', '12–25 mm chunks. Holds more as it breaks down over one to two years.'),
  ('sphagnum-moss', 'Sphagnum moss', 'organic', 'matrix', 0.95, 0, 0.12, 0.18837, 1.44653, 0.95, 0.15, 'typical-magnitude', 'Typical magnitude from the container-media literature (De Boodt & Verdonck 1972; Bunt 1988; Handreck & Black 2002); not a single measurement', 'Long-fibre moss. Depends heavily on how tightly it is packed.'),
  ('compost', 'Compost', 'organic', 'matrix', 0.65, 0, 0.1, 0.30752, 1.29977, 0.65, 0.22, 'typical-magnitude', 'Typical magnitude from the container-media literature (De Boodt & Verdonck 1972; Bunt 1988; Handreck & Black 2002); not a single measurement', 'Mature, screened. Slumps as it decomposes.'),
  ('grit', 'Grit or coarse sand', 'aggregate', 'skeleton', 0.4, 0.38, 0.05, 3.69227, 1.57023, 0.4, 0.03, 'typical-magnitude', 'Typical magnitude from the container-media literature (De Boodt & Verdonck 1972; Bunt 1988; Handreck & Black 2002); not a single measurement', '2–5 mm, non-porous: all of its pore space is between the grains.'),
  ('sand', 'Sand', 'mineral', 'matrix', 0.43, 0, 0.05, 0.145, 2.68, 0.43, 0.045, 'published-parameters', 'Carsel & Parrish (1988), Water Resour. Res. 24:755–769, class averages', 'Field-soil parameters. Dug, repacked soil in a pot is usually denser and drains worse than this suggests.'),
  ('loamy-sand', 'Loamy sand', 'mineral', 'matrix', 0.41, 0, 0.05, 0.124, 2.28, 0.41, 0.057, 'published-parameters', 'Carsel & Parrish (1988), Water Resour. Res. 24:755–769, class averages', 'Field-soil parameters. Dug, repacked soil in a pot is usually denser and drains worse than this suggests.'),
  ('sandy-loam', 'Sandy loam', 'mineral', 'matrix', 0.41, 0, 0.05, 0.075, 1.89, 0.41, 0.065, 'published-parameters', 'Carsel & Parrish (1988), Water Resour. Res. 24:755–769, class averages', 'Field-soil parameters. Dug, repacked soil in a pot is usually denser and drains worse than this suggests.'),
  ('loam', 'Loam', 'mineral', 'matrix', 0.43, 0, 0.05, 0.036, 1.56, 0.43, 0.078, 'published-parameters', 'Carsel & Parrish (1988), Water Resour. Res. 24:755–769, class averages', 'Field-soil parameters. Dug, repacked soil in a pot is usually denser and drains worse than this suggests.'),
  ('silt-loam', 'Silt loam', 'mineral', 'matrix', 0.45, 0, 0.05, 0.02, 1.41, 0.45, 0.067, 'published-parameters', 'Carsel & Parrish (1988), Water Resour. Res. 24:755–769, class averages', 'Field-soil parameters. Dug, repacked soil in a pot is usually denser and drains worse than this suggests.'),
  ('silt', 'Silt', 'mineral', 'matrix', 0.46, 0, 0.05, 0.016, 1.37, 0.46, 0.034, 'published-parameters', 'Carsel & Parrish (1988), Water Resour. Res. 24:755–769, class averages', 'Field-soil parameters. Dug, repacked soil in a pot is usually denser and drains worse than this suggests.'),
  ('sandy-clay-loam', 'Sandy clay loam', 'mineral', 'matrix', 0.39, 0, 0.05, 0.059, 1.48, 0.39, 0.1, 'published-parameters', 'Carsel & Parrish (1988), Water Resour. Res. 24:755–769, class averages', 'Field-soil parameters. Dug, repacked soil in a pot is usually denser and drains worse than this suggests.'),
  ('clay-loam', 'Clay loam', 'mineral', 'matrix', 0.41, 0, 0.05, 0.019, 1.31, 0.41, 0.095, 'published-parameters', 'Carsel & Parrish (1988), Water Resour. Res. 24:755–769, class averages', 'Field-soil parameters. Dug, repacked soil in a pot is usually denser and drains worse than this suggests.'),
  ('silty-clay-loam', 'Silty clay loam', 'mineral', 'matrix', 0.43, 0, 0.05, 0.01, 1.23, 0.43, 0.089, 'published-parameters', 'Carsel & Parrish (1988), Water Resour. Res. 24:755–769, class averages', 'Field-soil parameters. Dug, repacked soil in a pot is usually denser and drains worse than this suggests.'),
  ('sandy-clay', 'Sandy clay', 'mineral', 'matrix', 0.38, 0, 0.05, 0.027, 1.23, 0.38, 0.1, 'published-parameters', 'Carsel & Parrish (1988), Water Resour. Res. 24:755–769, class averages', 'Field-soil parameters. Dug, repacked soil in a pot is usually denser and drains worse than this suggests.'),
  ('silty-clay', 'Silty clay', 'mineral', 'matrix', 0.36, 0, 0.05, 0.005, 1.09, 0.36, 0.07, 'published-parameters', 'Carsel & Parrish (1988), Water Resour. Res. 24:755–769, class averages', 'Field-soil parameters. Dug, repacked soil in a pot is usually denser and drains worse than this suggests.'),
  ('clay', 'Clay', 'mineral', 'matrix', 0.38, 0, 0.05, 0.008, 1.09, 0.38, 0.068, 'published-parameters', 'Carsel & Parrish (1988), Water Resour. Res. 24:755–769, class averages', 'Field-soil parameters. Dug, repacked soil in a pot is usually denser and drains worse than this suggests.')
